  cat("    Mean         : ", round(m, 4), "  (target 1)\n")
  cat("    Std Dev      : ", round(sd_v, 4), "  (target 1)\n")
  if (.ks_test(exp_samples, qexp, pexp, alpha = 0.01)) {
