{"content": "#' Test suite for adaptive rejection sampling (ARS)
#'
#' Runs formal tests against known distributions (Normal, Exponential, Gamma)
#' and reports results in a clear PASS/FAIL format with descriptive statistics.
#'
#' @param n_samples Number of samples to draw for each test distribution.
#' @return Invisible NULL (side effects: prints test results, writes sample files).
test <- function(n_samples = 10000) {
  source("/app/ars.R")

  cat("============================================================\n")
  cat(" Adaptive Rejection Sampling — Test Suite\n")
  cat(" Gilks & Wild (1992) Implementation\n")
  cat("============================================================\n\n")

  passed  <- 0
  failed  <- 0

  ## ---- 1. INPUT VALIDATION TESTS ------------------------------------------
  cat("1. Input Validation Tests\n")
  cat("------------------------------------------------------------\n")

  lognorm <- function(x) -0.5 * x^2
  xlow    <- -Inf
  xup     <- Inf
  x0      <- c(-1, 0, 1)

  ## 1a. Negative n
  test_input_negative_n <- function() {
    tryCatch({
      ars(-5, lognorm, xlow, xup, x0)
      return(FALSE)  # should have thrown
    }, error = function(e) grepl("positive integer", e$message, ignore.case = TRUE))
  }
  ok <- test_input_negative_n()
  if (ok) { cat("  INPUT_NEGATIVE_N:   PASS\n"); passed <- passed + 1 } else { cat("  INPUT_NEGATIVE_N:   FAIL\n"); failed <- failed + 1 }

  ## 1b. Non-function log-density
  test_input_non_func <- function() {
    tryCatch({
      ars(10, 42, xlow, xup, x0)
      return(FALSE)
    }, error = function(e) grepl("'logdens' must be a function", e$message))
  }
  ok <- test_input_non_func()
  if (ok) { cat("  INPUT_NON_FUNC:     PASS\n"); passed <- passed + 1 } else { cat("  INPUT_NON_FUNC:     FAIL\n"); failed <- failed + 1 }

  ## 1c. xlow >= xup
  test_input_bounds <- function() {
    tryCatch({
      ars(10, lognorm, 5, 3, x0)
      return(FALSE)
    }, error = function(e) grepl("'xlow' must be strictly less", e$message))
  }
  ok <- test_input_bounds()
  if (ok) { cat("  INPUT_BAD_BOUNDS:   PASS\n"); passed <- passed + 1 } else { cat("  INPUT_BAD_BOUNDS:   FAIL\n"); failed <- failed + 1 }

  ## 1d. Too few initial abscissae
  test_input_few_x0 <- function() {
    tryCatch({
      ars(10, lognorm, xlow, xup, c(0, 1))
      return(FALSE)
    }, error = function(e) grepl("at least 3 points", e$message))
  }
  ok <- test_input_few_x0()
  if (ok) { cat("  INPUT_FEW_X0:       PASS\n"); passed <- passed + 1 } else { cat("  INPUT_FEW_X0:       FAIL\n"); failed <- failed + 1 }

  ## 1e. Initial abscissae outside domain
  test_input_x0_outside <- function() {
    tryCatch({
      ars(10, lognorm, 0, 10, c(-1, 0, 1))
      return(FALSE)
    }, error = function(e) grepl("strictly inside", e$message))
  }
  ok <- test_input_x0_outside()
  if (ok) { cat("  INPUT_X0_OUTSIDE:   PASS\n"); passed <- passed + 1 } else { cat("  INPUT_X0_OUTSIDE:   FAIL\n"); failed <- failed + 1 }

  cat("\n")

  ## ---- 2. NON-LOG-CONCAVE DENSITY TEST ------------------------------------
  cat("2. Log-Concavity Check\n")
  cat("------------------------------------------------------------\n")

  bimodal_logdens <- function(x) log(dnorm(x, mean = -3) + dnorm(x, mean = 3))
  tryCatch({
    ars(100, bimodal_logdens, -Inf, Inf, c(-5, 0, 5))
    cat("  NON_LOG_CONCAVE:  FAIL (no error thrown)\n")
    failed <- failed + 1
  }, error = function(e) {
    if (grepl("Log-concavity violated", e$message, ignore.case = TRUE)) {
      cat("  NON_LOG_CONCAVE:  PASS\n")
      passed <- passed + 1
    } else {
      cat("  NON_LOG_CONCAVE:  FAIL (unexpected error)\n")
      failed <- failed + 1
    }
  })
  cat("\n")

  ## ---- 3. DISTRIBUTIONAL TESTS --------------------------------------------
  cat("3. Distributional Tests\n")
  cat("------------------------------------------------------------\n")

  ## 3a. Standard Normal -------------------------------------------------------
  cat("  [Normal] Generating ", n_samples, " samples ... \n")
  set.seed(42)
  normal_samples <- ars(n_samples,
                         logdens = function(x) -0.5 * x^2,
                         xlow    = -Inf, xup = Inf,
                         x0      = c(-2, 0, 2))
  writeLines(as.character(normal_samples), "/app/normal_samples.txt")
  m  <- mean(normal_samples)
  sd_v <- sd(normal_samples)
  cat("    Mean         : ", round(m, 4), "  (target 0)\n")
  cat("    Std Dev      : ", round(sd_v, 4), "  (target 1)\n")
  if (.ks_test(normal_samples, qnorm, pnorm, alpha = 0.01)) {
    cat("  NORMAL: PASS\n\n")
    passed <- passed + 1
  } else {
    cat("  NORMAL: FAIL\n\n")
    failed <- failed + 1
  }

  ## 3b. Exponential -----------------------------------------------------------
  cat("  [Exponential] Generating ", n_samples, " samples ... \n")
  set.seed(123)
  exp_samples <- ars(n_samples,
                     logdens = function(x) -x,
                     xlow    = 0, xup = Inf,
                     x0      = c(0.1, 1, 3))
  writeLines(as.character(exp_samples), "/app/exponential_samples.txt")
  m  <- mean(exp_samples)
  sd_v <- sd(exp_samples)
  cat("    Mean         : ", round(m, 4), "  (target 1)\n")
  cat("    Std Dev      : ", round(sd_v, 4), "  (target 1)\n")
  if (.ks_test(exp_samples, qexp, pexp, alpha = 0.01)) {
    cat("  EXPONENTIAL: PASS\n\n")
    passed <- passed + 1
  } else {
    cat("  EXPONENTIAL: FAIL\n\n")
    failed <- failed + 1
  }

  ## 3c. Gamma(2,1) ------------------------------------------------------------
  cat("  [Gamma(2,1)] Generating ", n_samples, " samples ... \n")
  set.seed(456)
  gamma_samples <- ars(n_samples,
                       logdens = function(x) (2 - 1) * log(x) - x,
                       xlow    = 0, xup = Inf,
                       x0      = c(0.2, 1, 3))
  m  <- mean(gamma_samples)
  sd_v <- sd(gamma_samples)
  cat("    Mean         : ", round(m, 4), "  (target 2)\n")
  cat("    Std Dev      : ", round(sd_v, 4), "  (target sqrt(2))\n")
  if (.ks_test(gamma_samples, qgamma, pgamma, alpha = 0.01,
               shape = 2, rate = 1)) {
    cat("  GAMMA: PASS\n\n")
    passed <- passed + 1
  } else {
    cat("  GAMMA: FAIL\n\n")
    failed <- failed + 1
  }

  ## 3d. Cauchy (log-concave, heavy-tailed) ------------------------------------
  cat("  [Cauchy] Generating ", n_samples, " samples ... \n")
  set.seed(789)
  cauchy_samples <- ars(n_samples,
                        logdens = function(x) -log(1 + x^2),
                        xlow    = -Inf, xup = Inf,
                        x0      = c(-2, 0, 2))
  m  <- mean(cauchy_samples)
  sd_v <- sd(cauchy_samples)
  cat("    Mean         : ", round(m, 4), "  (undefined for Cauchy)\n")
  cat("    Std Dev      : ", round(sd_v, 4), "  (undefined for Cauchy)\n")
  if (.ks_test(cauchy_samples, qcauchy, pcauchy, alpha = 0.01)) {
    cat("  CAUCHY: PASS\n\n")
    passed <- passed + 1
  } else {
    cat("  CAUCHY: FAIL\n\n")
    failed <- failed + 1
  }

  ## 3e. Log-Normal(0,1) ------------------------------------------------------
  cat("  [LogNormal] Generating ", n_samples, " samples ... \n")
  set.seed(111)
  lnorm_samples <- ars(n_samples,
                       logdens = function(x) -0.5 * (log(x))^2 - log(x),
                       xlow    = 0, xup = Inf,
                       x0      = c(0.1, 1, 5))
  m  <- mean(lnorm_samples)
  sd_v <- sd(lnorm_samples)
  cat("    Mean         : ", round(m, 4), "  (target ", round(exp(0.5), 4), ")\n")
  cat("    Std Dev      : ", round(sd_v, 4), "  (target ", round(sqrt(exp(1)-1)*exp(0.5), 4), ")\n")
  if (.ks_test(lnorm_samples, qlnorm, plnorm, alpha = 0.01)) {
    cat("  LOGNORMAL: PASS\n\n")
    passed <- passed + 1
  } else {
    cat("  LOGNORMAL: FAIL\n\n")
    failed <- failed + 1
  }

  ## ---- 4. SUMMARY -----------------------------------------------------------
  cat("============================================================\n")
  cat(" Summary: ", passed, " passed, ", failed, " failed\n")
  cat("============================================================\n")

  invisible(list(passed = passed, failed = failed))
}

## ---- helper: two-sample KS test (vs theoretical CDF) -----------------------
#' Perform a Kolmogorov-Smirnov goodness-of-fit test against a theoretical CDF.
#'
#' @param samples Numeric vector of samples.
#' @param qfun Quantile function (e.g., qnorm).
#' @param pfun CDF function (e.g., pnorm).
#' @param alpha Significance level.
#' @param ... Additional arguments passed to pfun/qfun.
#' @return Logical; TRUE if the KS test does not reject the null hypothesis
#'   (samples come from the target distribution).
.ks_test <- function(samples, qfun, pfun, alpha = 0.05, ...) {
  # Use one-sample KS test against the theoretical CDF.
  args <- list(...)
  ks_res <- ks.test(samples, pfun, ...)
  sig <- ks_res$p.value < alpha
  direction <- ifelse(sig, "reject H0", "fail to reject H0")
  cat("    KS statistic : ", round(ks_res$statistic, 4),
      ", p-value      : ", format(ks_res$p.value, scientific = FALSE),
      " -> ", direction, "\n", sep = "")
  return(!sig)
}
