{"content": "#' Adaptive Rejection Sampling (ARS)
#'
#' Implements the adaptive rejection sampler of Gilks & Wild (1992) for
#' generating random variates from a log-concave density.
#'
#' @param n Number of samples to generate.
#' @param logdens Function returning the log of the (possibly unnormalized)
#'   density, evaluated vectorized over x. Must be log-concave.
#' @param xlow Lower bound of the domain (finite or -Inf).
#' @param xup Upper bound of the domain (finite or Inf).
#' @param x0 Initial abscissae at which to evaluate the log-density.
#'   Must contain at least 3 points strictly inside (xlow, xup).
#' @param verbose Logical; if TRUE, print progress messages.
#' @return A numeric vector of samples from the target distribution.
#' @references Gilks, W. R., & Wild, P. (1992). Adaptive rejection sampling
#'   for Gibbs sampling. Journal of the Royal Statistical Society: Series C,
#'   41(2), 337-348.
ars <- function(n, logdens, xlow, xup, x0, verbose = FALSE) {
  ## ---- input validation ----------------------------------------------------
  check <- .validate_inputs(n, logdens, xlow, xup, x0)
  if (!isTRUE(check$valid)) {
    stop(check$message)
  }

  n       <- check$n
  logdens <- check$logdens
  xlow    <- check$xlow
  xup     <- check$xup
  x0      <- sort(check$x0)

  ## ---- initialize nodes and log-densities ----------------------------------
  x      <- x0
  logf   <- logdens(x)
  logfp  <- rep(NA_real_, length(x))  # derivatives at nodes
  for (i in seq_along(x)) {
    logfp[i] <- .num_derivative(logdens, x[i])
  }

  samples <- integer(0)

  ## ---- main sampling loop --------------------------------------------------
  while (length(samples) < n) {
    ## Build the lower envelope (piecewise linear in log-space, i.e.
    ## piecewise exponential in density space).
    env <- .build_lower_envelope(x, logf, logfp, xlow, xup)

    ## Sample a candidate from the lower envelope.
    u      <- runif(1)
    xx     <- .sample_from_envelope(u, env, xlow, xup)
    logfxx <- logdens(xx)

    ## Log-concavity check: the candidate must lie below the lower envelope.
    if (logfxx > env$y[env$idx] + env$m[env$idx] * (xx - env$xl[env$idx])) {
      stop(
        "Log-concavity violated at x = ", round(xx, 6),
        ". The supplied log-density does not appear to be log-concave."
      )
    }

    ## Acceptance test: U <= exp(logf(xx) - envelope(xx)).
    u2 <- runif(1)
    accept_log <- logfxx - (env$y[env$idx] + env$m[env$idx] * (xx - env$xl[env$idx]))
    if (u2 <= exp(accept_log)) {
      samples <- c(samples, xx)
      if (verbose) {
        cat("Accepted sample:", round(xx, 6), "\n")
      }
    }

    ## Even if rejected, add the point to the node set so the envelope
    ## improves (per Gilks & Wild 1992, Section 3).
    if (xx > xlow && xx < xup) {
      .add_node(x, logf, logfp, logdens, xx)
      env <- .build_lower_envelope(x, logf, logfp, xlow, xup)
    }
  }

  return(samples[1:n])
}

## ---- helper: validate inputs -----------------------------------------------
.validate_inputs <- function(n, logdens, xlow, xup, x0) {
  out <- list(valid = TRUE, n = n, logdens = logdens,
              xlow = xlow, xup = xup, x0 = x0)

  ## n must be a positive integer
  if (length(n) != 1 || !is.numeric(n) || n != as.integer(n) || n <= 0) {
    out$valid <- FALSE
    out$message <- "'n' must be a positive integer."
    return(out)
  }
  out$n <- as.integer(n)

  ## logdens must be a function
  if (!is.function(logdens)) {
    out$valid <- FALSE
    out$message <- "'logdens' must be a function."
    return(out)
  }

  ## Domain bounds
  if (!is.numeric(xlow) || length(xlow) != 1 || is.nan(xlow) || is.infinite(xlow)) {
    out$valid <- FALSE
    out$message <- "'xlow' must be a finite numeric value."
    return(out)
  }
  if (!is.numeric(xup) || length(xup) != 1 || is.nan(xup) || is.infinite(xup)) {
    out$valid <- FALSE
    out$message <- "'xup' must be a finite numeric value."
    return(out)
  }
  if (xlow >= xup) {
    out$valid <- FALSE
    out$message <- "'xlow' must be strictly less than 'xup'."
    return(out)
  }
  out$xlow <- xlow
  out$xup  <- xup

  ## Initial abscissae
  if (!is.numeric(x0) || length(x0) < 3) {
    out$valid <- FALSE
    out$message <- "'x0' must be a numeric vector of at least 3 points."
    return(out)
  }
  x0_sorted <- sort(x0)
  if (any(x0_sorted <= xlow) || any(x0_sorted >= xup)) {
    out$valid <- FALSE
    out$message <- "All initial abscissae must lie strictly inside (xlow, xup)."
    return(out)
  }
  out$x0 <- x0_sorted

  ## Quick sanity check: log-density should evaluate without error.
  tryCatch({
    vals <- logdens(x0)
    if (!is.numeric(vals) || length(vals) != length(x0)) {
      stop("logdens did not return a numeric vector of the same length.")
    }
    if (any(is.nan(vals) | is.infinite(vals))) {
      out$valid <- FALSE
      out$message <- "log-density returned NaN or Inf at some initial points."
      return(out)
    }
  }, error = function(e) {
    out$valid <- FALSE
    out$message <- paste("Error evaluating log-density:", e$message)
  })

  return(out)
}

## ---- helper: numerical derivative ------------------------------------------
.num_derivative <- function(f, x, h = 1e-7) {
  (f(x + h) - f(x - h)) / (2 * h)
}

## ---- helper: add a node and update log-derivatives -------------------------
.add_node <- function(x, logf, logfp, logdens, xx) {
  idx <- .find_insert_pos(x, xx)
  x      <- c(x[1:(idx - 1)], xx, x[idx:length(x)])
  logf   <- c(logf[1:(idx - 1)], logdens(xx), logf[idx:length(logf)])
  logfp  <- c(logfp[1:(idx - 1)], .num_derivative(logdens, xx), logfp[idx:length(logfp)])
  assign("x",      x,      envir = .GlobalEnv)
  assign("logf",   logf,   envir = .GlobalEnv)
  assign("logfp",  logfp,  envir = .GlobalEnv)
  NULL
}

## ---- helper: find insert position ------------------------------------------
.find_insert_pos <- function(x, xx) {
  for (i in seq_along(x)) {
    if (xx < x[i]) return(i)
  }
  length(x) + 1
}

## ---- helper: build the lower envelope (tangents + secants) -----------------
.build_lower_envelope <- function(x, logf, logfp, xlow, xup) {
  k <- length(x)
  m <- numeric(k)   # slope of the lower-bound line on each sub-interval
  y <- numeric(k)   # intercept (value at x) on the lower-bound line
  xl <- numeric(k)  # left endpoint of each sub-interval
  xr <- numeric(k)  # right endpoint of each sub-interval
  w  <- numeric(k)  # weight (unnormalized area contribution)

  for (i in 1:k) {
    if (i == 1) {
      ## Leftmost interval: use the tangent at x[1], truncated by x[2].
      m[i] <- logfp[i]
      y[i] <- logf[i] - m[i] * x[i]
      xl[i] <- xlow
      xr[i] <- x[i + 1]
    } else if (i == k) {
      ## Rightmost interval: use the tangent at x[k], truncated by x[k-1].
      m[i] <- logfp[i]
      y[i] <- logf[i] - m[i] * x[i]
      xl[i] <- x[i - 1]
      xr[i] <- xup
    } else {
      ## Middle interval: upper envelope is min(tangent at i, secant with i-1, secant with i+1).
      ## The lower envelope is the tangent line at x[i].
      m[i] <- logfp[i]
      y[i] <- logf[i] - m[i] * x[i]
      xl[i] <- x[i - 1]
      xr[i] <- x[i + 1]
    }

    ## Compute the (log) integral of exp(line) over [xl, xr].
    a <- m[i]
    b <- y[i]
    left  <- xl[i]
    right <- xr[i]
    if (abs(a) < 1e-12) {
      integrand <- (right - left) * exp(b)
    } else {
      integrand <- (exp(a * right + b) - exp(a * left + b)) / a
    }
    w[i] <- integrand
  }

  return(list(m = m, y = y, xl = xl, xr = xr, w = w, x = x, logf = logf, logfp = logfp))
}

## ---- helper: sample from the lower envelope --------------------------------
.sample_from_envelope <- function(u, env, xlow, xup) {
  w  <- env$w
  xl <- env$xl
  xr <- env$xr
  m  <- env$m
  y  <- env$y

  cumw <- cumsum(w)
  total <- cumw[length(cumw)]
  u_scaled <- u * total

  idx <- which.max(cumw >= u_scaled)

  ## Invert the CDF of the truncated exponential on [xl[idx], xr[idx]].
  a <- m[idx]
  b <- y[idx]
  left  <- xl[idx]
  right <- xr[idx]

  if (abs(a) < 1e-12) {
    ## Constant density on this interval.
    xx <- left + u * (right - left)
  } else {
    cdf_left  <- exp(a * left + b)
    cdf_right <- exp(a * right + b)
    portion   <- u * (cdf_right - cdf_left) + cdf_left
    xx <- (log(portion) - b) / a
  }

  return(xx)
}

## ---- helper: evaluate lower envelope at a point ----------------------------
.envelope_value <- function(xx, env) {
  x <- env$x
  idx <- max(which(x <= xx))
  if (idx == 0) idx <- 1
  if (idx > length(x)) idx <- length(x)
  env$y[idx] + env$m[idx] * (xx - env$x[idx])
}
