{"content": "#' Adaptive Rejection Sampling (ARS)
#'
#' Implements the adaptive rejection sampler of Gilks & Wild (1992) for
#' generating random variates from a log-concave density.
#'
#' @param n Number of samples to generate.
#' @param logdens Function returning the log of the (possibly unnormalized)
#'   density, evaluated vectorized over x. Must be log-concave.
#' @param xlow Lower bound of the domain (finite or -Inf).
#' @param xup Upper bound of the domain (finite or Inf).
#' @param x0 Initial abscissae at which to evaluate the log-density.
#'   Must contain at least 3 points strictly inside (xlow, xup).
#' @param verbose Logical; if TRUE, print progress messages.
#' @return A numeric vector of samples from the target distribution.
#' @references Gilks, W. R., & Wild, P. (1992). Adaptive rejection sampling
#'   for Gibbs sampling. Journal of the Royal Statistical Society: Series C,
#'   41(2), 337-348.
ars <- function(n, logdens, xlow, xup, x0, verbose = FALSE) {
  ## ---- input validation ----------------------------------------------------
  check <- .validate_inputs(n, logdens, xlow, xup, x0)
  if (!isTRUE(check$valid)) {
    stop(check$message)
  }

  n       <- check$n
  logdens <- check$logdens
  xlow    <- check$xlow
  xup     <- check$xup
  x0      <- sort(check$x0)

  ## ---- mutable state via environment ---------------------------------------
  state <- new.env(parent = emptyenv())
  state$x      <- x0
  state$logf   <- logdens(x0)
  state$logfp  <- sapply(x0, function(xi) .num_derivative(logdens, xi))

  samples <- integer(0)

  ## ---- main sampling loop --------------------------------------------------
  while (length(samples) < n) {
    env <- .build_lower_envelope(state$x, state$logf, state$logfp, xlow, xup)

    ## Sample a candidate from the lower envelope.
    u      <- runif(1)
    xx     <- .sample_from_envelope(u, env)
    logfxx <- logdens(xx)

    ## Log-concavity check: the candidate must lie below the lower envelope.
    env_val <- .envelope_value(xx, env)
    if (logfxx > env_val) {
      stop(
        "Log-concavity violated at x = ", round(xx, 6),
        ". The supplied log-density does not appear to be log-concave."
      )
    }

    ## Acceptance test: U <= exp(logf(xx) - envelope(xx)).
    u2 <- runif(1)
    accept_log <- logfxx - env_val
    if (u2 <= exp(accept_log)) {
      samples <- c(samples, xx)
      if (verbose) {
        cat("Accepted sample:", round(xx, 6), "\n")
      }
    }

    ## Even if rejected, add the point to the node set so the envelope improves.
    if (!is.infinite(xx) && xx > xlow && xx < xup) {
      .add_node(state, logdens, xx)
    }
  }

  return(samples[1:n])
}

## ---- helper: validate inputs -----------------------------------------------
.validate_inputs <- function(n, logdens, xlow, xup, x0) {
  out <- list(valid = TRUE, n = n, logdens = logdens,
              xlow = xlow, xup = xup, x0 = x0)

  if (length(n) != 1 || !is.numeric(n) || n != as.integer(n) || n <= 0) {
    out$valid <- FALSE
    out$message <- "'n' must be a positive integer."
    return(out)
  }
  out$n <- as.integer(n)

  if (!is.function(logdens)) {
    out$valid <- FALSE
    out$message <- "'logdens' must be a function."
    return(out)
  }

  if (!is.numeric(xlow) || length(xlow) != 1 || is.nan(xlow)) {
    out$valid <- FALSE
    out$message <- "'xlow' must be a numeric value (may be -Inf)."
    return(out)
  }
  if (!is.numeric(xup) || length(xup) != 1 || is.nan(xup)) {
    out$valid <- FALSE
    out$message <- "'xup' must be a numeric value (may be Inf)."
    return(out)
  }
  if (!is.infinite(xlow) && !is.infinite(xup) && xlow >= xup) {
    out$valid <- FALSE
    out$message <- "'xlow' must be strictly less than 'xup'."
    return(out)
  }
  out$xlow <- xlow
  out$xup  <- xup

  if (!is.numeric(x0) || length(x0) < 3) {
    out$valid <- FALSE
    out$message <- "'x0' must be a numeric vector of at least 3 points."
    return(out)
  }
  x0_sorted <- sort(x0)
  if (!is.infinite(xlow) && any(x0_sorted <= xlow)) {
    out$valid <- FALSE
    out$message <- "All initial abscissae must lie strictly inside (xlow, xup)."
    return(out)
  }
  if (!is.infinite(xup) && any(x0_sorted >= xup)) {
    out$valid <- FALSE
    out$message <- "All initial abscissae must lie strictly inside (xlow, xup)."
    return(out)
  }
  out$x0 <- x0_sorted

  tryCatch({
    vals <- logdens(x0)
    if (!is.numeric(vals) || length(vals) != length(x0)) {
      stop("logdens did not return a numeric vector of the same length.")
    }
    if (any(is.nan(vals) | is.infinite(vals))) {
      out$valid <- FALSE
      out$message <- "log-density returned NaN or Inf at some initial points."
      return(out)
    }
  }, error = function(e) {
    out$valid <- FALSE
    out$message <- paste("Error evaluating log-density:", e$message)
  })

  return(out)
}

## ---- helper: numerical derivative (central difference) ---------------------
.num_derivative <- function(f, x, h = 1e-7) {
  (f(x + h) - f(x - h)) / (2 * h)
}

## ---- helper: find insert position in sorted vector -------------------------
.find_insert_pos <- function(x, xx) {
  for (i in seq_along(x)) {
    if (xx < x[i]) return(i)
  }
  length(x) + 1
}

## ---- helper: add a node to mutable state -----------------------------------
.add_node <- function(state, logdens, xx) {
  idx <- .find_insert_pos(state$x, xx)
  x_vec      <- state$x
  logf_vec   <- state$logf
  logfp_vec  <- state$logfp

  x_vec      <- c(x_vec[1:(idx - 1)], xx, x_vec[idx:length(x_vec)])
  logf_vec   <- c(logf_vec[1:(idx - 1)], logdens(xx), logf_vec[idx:length(logf_vec)])
  logfp_vec  <- c(logfp_vec[1:(idx - 1)], .num_derivative(logdens, xx), logfp_vec[idx:length(logfp_vec)])

  state$x      <- x_vec
  state$logf   <- logf_vec
  state$logfp  <- logfp_vec
}

## ---- helper: build the lower envelope (tangent lines) ----------------------
.build_lower_envelope <- function(x, logf, logfp, xlow, xup) {
  k <- length(x)
  m   <- numeric(k)
  y   <- numeric(k)
  xl  <- numeric(k)
  xr  <- numeric(k)
  w   <- numeric(k)
  half_infinite <- logical(k)  # TRUE if interval extends to infinity

  for (i in 1:k) {
    m[i]  <- logfp[i]
    y[i]  <- logf[i] - m[i] * x[i]
    xl[i] <- ifelse(i == 1, xlow, x[i - 1])
    xr[i] <- ifelse(i == k, xup, x[i + 1])
    half_infinite[i] <- is.infinite(xl[i]) | is.infinite(xr[i])

    a <- m[i]
    b <- y[i]
    left  <- xl[i]
    right <- xr[i]

    if (abs(a) < 1e-12) {
      if (!half_infinite[i]) {
        w[i] <- (right - left) * exp(b)
      } else {
        w[i] <- NA_real_  # will be handled below
      }
    } else if (!half_infinite[i]) {
      w[i] <- (exp(a * right + b) - exp(a * left + b)) / a
    } else {
      ## Half-infinite interval: need special handling.
      ## If left is -Inf and a > 0: integral = exp(a*right+b)/a
      ## If right is Inf and a < 0: integral = exp(a*left+b)/(-a)
      if (is.infinite(left) && a > 0) {
        w[i] <- exp(a * right + b) / a
      } else if (is.infinite(right) && a < 0) {
        w[i] <- exp(a * left + b) / (-a)
      } else {
        w[i] <- NA_real_
      }
    }
  }

  return(list(m = m, y = y, xl = xl, xr = xr, w = w, x = x, half_inf = half_infinite))
}

## ---- helper: sample from the lower envelope -------------------------------
.sample_from_envelope <- function(u, env) {
  w  <- env$w
  xl <- env$xl
  xr <- env$xr
  m  <- env$m
  y  <- env$y
  hi <- env$half_inf

  ## Filter out any NA weights (shouldn't happen for valid inputs)
  valid <- !is.na(w)
  if (!all(valid)) {
    w  <- w[valid]
    xl <- xl[valid]
    xr <- xr[valid]
    m  <- m[valid]
    y  <- y[valid]
    hi <- hi[valid]
  }

  cumw  <- cumsum(w)
  total <- cumw[length(cumw)]
  u_scaled <- u * total

  idx <- which.max(cumw >= u_scaled)

  a <- m[idx]
  b <- y[idx]
  left  <- xl[idx]
  right <- xr[idx]

  if (abs(a) < 1e-12) {
    xx <- left + u * (right - left)
  } else if (is.infinite(left) && a > 0) {
    ## Truncated exponential on (-Inf, right]
    cdf_at_right <- exp(a * right + b)
    portion <- u * cdf_at_right
    xx <- (log(portion) - b) / a
  } else if (is.infinite(right) && a < 0) {
    ## Truncated exponential on [left, Inf)
    cdf_at_left <- exp(a * left + b)
    portion <- (1 - u) * cdf_at_left
    xx <- (log(portion) - b) / a
  } else {
    cdf_left  <- exp(a * left + b)
    cdf_right <- exp(a * right + b)
    portion   <- u * (cdf_right - cdf_left) + cdf_left
    xx <- (log(portion) - b) / a
  }

  return(xx)
}

## ---- helper: evaluate lower envelope at a point ---------------------------
.envelope_value <- function(xx, env) {
  x <- env$x
  idx <- max(which(x <= xx))
  if (idx == 0) idx <- 1
  if (idx > length(x)) idx <- length(x)
  return(env$y[idx] + env$m[idx] * (xx - env$x[idx]))
}
