    .build_lower_envelope(state$x, state$logf, state$logfp, -Inf, Inf)
  }, error = function(e) {
    cat("ERROR at iter", iter, "\n")
    cat("x:", state$x, "\n")
    cat("logfp:", state$logfp, "\n")
    cat("any NA in x:", any(is.na(state$x)), "\n")
    cat("any NA in logfp:", any(is.na(state$logfp)), "\n")
    cat("any NaN in x:", any(is.nan(state$x)), "\n")
    cat("any NaN in logfp:", any(is.nan(state$logfp)), "\n")
    return(NULL)
  })
  if (is.null(env)) break

  u <- runif(1)
  xx <- .sample_from_envelope(u, env)
  logfxx <- logdens(xx)
  env_val <- .envelope_value(xx, env)

  if (logfxx > env_val) {
    cat("Log-concavity violated at iter", iter, "xx=", xx, "\n")
    break
  }

  u2 <- runif(1)
  if (u2 <= exp(logfxx - env_val)) {
    samples <- c(samples, xx)
  }

  if (!is.infinite(xx) && xx > -Inf && xx < Inf && !is.na(xx)) {
    .add_node(state, logdens, xx)
  }

  if (length(samples) >= n) {
    cat("Reached n samples at iter", iter, "\n")
    break
  }
}
' 2>&1"}

