{"content": "#' Adaptive Rejection Sampling (ARS)
#'
#' Implements the adaptive rejection sampler of Gilks & Wild (1992) for
#' generating random variates from a log-concave density.
#'
#' @param n Number of samples to generate.
#' @param logdens Function returning the log of the (possibly unnormalized)
#'   density, evaluated vectorized over x. Must be log-concave.
#' @param xlow Lower bound of the domain (finite or -Inf).
#' @param xup Upper bound of the domain (finite or Inf).
#' @param x0 Initial abscissae at which to evaluate the log-density.
#'   Must contain at least 3 points strictly inside (xlow, xup).
#' @param verbose Logical; if TRUE, print progress messages.
#' @return A numeric vector of samples from the target distribution.
#' @references Gilks, W. R., & Wild, P. (1992). Adaptive rejection sampling
#'   for Gibbs sampling. Journal of the Royal Statistical Society: Series C,
#'   41(2), 337-348.
ars <- function(n, logdens, xlow, xup, x0, verbose = FALSE) {
  ## ---- input validation ----------------------------------------------------
  check <- .validate_inputs(n, logdens, xlow, xup, x0)
  if (!isTRUE(check$valid)) {
    stop(check$message)
  }

  n       <- check$n
  logdens <- check$logdens
  xlow    <- check$xlow
  xup     <- check$xup
  x0      <- sort(check$x0)

  ## ---- initialize nodes and log-densities ----------------------------------
  x      <- x0
  logf   <- logdens(x)
  logfp  <- rep(NA_real_, length(x))  # derivatives at nodes
  for (i in seq_along(x)) {
    logfp[i] <- .num_derivative(logdens, x[i])
  }

  samples <- integer(0)

  ## ---- main sampling loop --------------------------------------------------
  while (length(samples) < n) {
    ## Build the lower envelope (piecewise linear in log-space, i.e.
    ## piecewise exponential in density space).
    env <- .build_lower_envelope(x, logf, logfp, xlow, xup)

    ## Sample a candidate from the lower envelope.
    u      <- runif(1)
    xx     <- .sample_from_envelope(u, env, xlow, xup)
    logfxx <- logdens(xx)

    ## Log-concavity check: the candidate must lie below the lower envelope.
    if (logfxx > env$y[env$idx] + env$m[env$idx] * (xx - env$xl[env$idx])) {
      stop(
        "Log-concavity violated at x = ", round(xx, 6),
        ". The supplied log-density does not appear to be log-concave."
      )
    }

    ## Acceptance test: U <= exp(logf(xx) - envelope(xx)).
    u2 <- runif(1)
    accept_log <- logfxx - (env$y[env$idx] + env$m[env$idx] * (xx - env$xl[env$idx]))
    if (u2 <= exp(accept_log)) {
      samples <- c(samples, xx)
      if (verbose) {
        cat("Accepted sample:", round(xx, 6), "\n")
      }
    }

    ## Even if rejected, add the point to the node set so the envelope
    ## improves (per Gilks & Wild 1992, Section 3).
    if (xx > xlow && xx < xup) {
      .add_node(x, logf, logfp, logdens, xx)
      env <- .build_lower_envelope(x, logf, logfp, xlow, xup)
    }
  }

  return(samples[1:n])
}

## ---- helper: validate inputs -----------------------------------------------
.validate_inputs <- function(n, logdens, xlow, xup, x0) {
  out <- list(valid = TRUE, n = n, logdens = logdens,
              xlow = xlow, xup = xup, x0 = x0)

  ## n must be a positive integer
  if (length(n) != 1 || !is.numeric(n) || n != as.integer(n) || n <= 0) {
    out$valid <- FALSE
    out$message <- "'n' must be a positive integer."
    return(out)
  }
  out$n <- as.integer(n)

  ## logdens must be a function
  if (!is.function(logdens)) {
    out$valid <- FALSE
    out$message <- "'logdens' must be a function."
    return(out)
  }

  ## Domain bounds
  if (!is.numeric(xlow) || length(xlow) != 1 || is.nan(xlow) || is.infinite(xlow)) {
    out$valid <- FALSE
    out$message <- "'xlow' must be a finite numeric value."
    return(out)
  }
  if (!is.numeric(xup) || length(xup) != 1 || is.nan(xup) || is.infinite(xup)) {
    out$valid <- FALSE
    out$message <- "'xup' must be a finite numeric value."
    return(out)
  }
  if (xlow >= xup) {
    out$valid <- FALSE
    out$message <- "'xlow' must be strictly less than 'xup'."
    return(out)
  }
  out$xlow <- xlow
  out$xup  <- xup

  ## Initial abscissae
  if (!is.numeric(x0) || length(x0) < 3) {
    out$valid <- FALSE
    out$message <- "'x0' must be a numeric vector of at least 3 points."
    return(out)
  }
  x0_sorted <- sort(x0)
  if (any(x0_sorted <= xlow) || any(x0_sorted >= xup)) {
    out$valid <- FALSE
    out$message <- "All initial abscissae must lie strictly inside (xlow, xup)."
    return(out)
  }
  out$x0 <- x0_sorted

  ## Quick sanity check: log-density should evaluate without error.
  tryCatch({
    vals <- logdens(x0)
    if (!is.numeric(vals) || length(vals) != length(x0)) {
      stop("logdens did not return a numeric vector of the same length.")
    }
    if (any(is.nan(vals) | is.infinite(vals))) {
      out$valid <- FALSE
      out$message <- "log-density returned NaN or Inf at some initial points."
      return(out)
    }
  }, error = function(e) {
    out$valid <- FALSE
    out$message <- paste("Error evaluating log-density:", e$message)
  })

  return(out)
}

## ---- helper: numerical derivative ------------------------------------------
.num_derivative <- function(f, x, h = 1e-7) {
  (f(x + h) - f(x - h)) / (2 * h)
}

## ---- helper: add a node and update log-derivatives -------------------------
.add_node <- function(x, logf, logfp, logdens, xx) {
  idx <- .find_insert_pos(x, xx)
  x      <- c(x[1:(idx - 1)], xx, x[idx:length(x)])
  logf   <- c(logf[1:(idx - 1)], logdens(xx), logf[idx:length(logf)])
  logfp  <- c(logfp[1:(idx - 1)], .num_derivative(logdens, xx), logfp[idx:length(logfp)])
  assign("x",      x,      envir = .GlobalEnv)
  assign("logf",   logf,   envir = .GlobalEnv)
  assign("logfp",  logfp,  envir = .GlobalEnv)
  NULL
}

## ---- helper: find insert position ------------------------------------------
.find_insert_pos <- function(x, xx) {
  for (i in seq_along(x)) {
    if (xx < x[i]) return(i)
  }
  length(x) + 1
}

## ---- helper: build the lower envelope (tangents + secants) -----------------
.build_lower_envelope <- function(x, logf, logfp, xlow, xup) {
  k <- length(x)
  m <- numeric(k)   # slope of the lower-bound line on each sub-interval
  y <- numeric(k)   # intercept (value at x) on the lower-bound line
  xl <- numeric(k)  # left endpoint of each sub-interval
  xr <- numeric(k)  # right endpoint of each sub-interval
  w  <- numeric(k)  # weight (unnormalized area contribution)

  for (i in 1:k) {
    if (i == 1) {
      ## Leftmost interval: use the tangent at x[1], truncated by x[2].
      m[i] <- logfp[i]
      y[i] <- logf[i] - m[i] * x[i]
      xl[i] <- xlow
      xr[i] <- x[i + 1]
    } else if (i == k) {
      ## Rightmost interval: use the tangent at x[k], truncated by x[k-1].
      m[i] <- logfp[i]
      y[i] <- logf[i] - m[i] * x[i]
      xl[i] <- x[i - 1]
      xr[i] <- xup
    } else {
      ## Middle interval: upper envelope is min(tangent at i, secant with i-1, secant with i+1).
      ## The lower envelope is the tangent line at x[i].
      m[i] <- logfp[i]
      y[i] <- logf[i] - m[i] * x[i]
      xl[i] <- x[i - 1]
      xr[i] <- x[i + 1]
    }

    ## Compute the (log) integral of exp(line) over [xl, xr].
    a <- m[i]
    b <- y[i]
    left  <- xl[i]
    right <- xr[i]
    if (abs(a) < 1e-12) {
      integrand <- (right - left) * exp(b)
    } else {
      integrand <- (exp(a * right + b) - exp(a * left + b)) / a
    }
    w[i] <- integrand
  }

  return(list(m = m, y = y, xl = xl, xr = xr, w = w, x = x, logf = logf, logfp = logfp))
}

## ---- helper: sample from the lower envelope --------------------------------
.sample_from_envelope <- function(u, env, xlow, xup) {
  w  <- env$w
  xl <- env$xl
  xr <- env$xr
  m  <- env$m
  y  <- env$y

  cumw <- cumsum(w)
  total <- cumw[length(cumw)]
  u_scaled <- u * total

  idx <- which.max(cumw >= u_scaled)

  ## Invert the CDF of the truncated exponential on [xl[idx], xr[idx]].
  a <- m[idx]
  b <- y[idx]
  left  <- xl[idx]
  right <- xr[idx]

  if (abs(a) < 1e-12) {
    ## Constant density on this interval.
    xx <- left + u * (right - left)
  } else {
    cdf_left  <- exp(a * left + b)
    cdf_right <- exp(a * right + b)
    portion   <- u * (cdf_right - cdf_left) + cdf_left
    xx <- (log(portion) - b) / a
  }

  return(xx)
}

## ---- helper: evaluate lower envelope at a point ----------------------------
.envelope_value <- function(xx, env) {
  x <- env$x
  idx <- max(which(x <= xx))
  if (idx == 0) idx <- 1
  if (idx > length(x)) idx <- length(x)
  env$y[idx] + env$m[idx] * (xx - env$x[idx])
}
", "path": "/app/ars.R"}

{"content": "#' Test suite for adaptive rejection sampling (ARS)
#'
#' Runs formal tests against known distributions (Normal, Exponential, Gamma)
#' and reports results in a clear PASS/FAIL format with descriptive statistics.
#'
#' @param n_samples Number of samples to draw for each test distribution.
#' @return Invisible NULL (side effects: prints test results, writes sample files).
test <- function(n_samples = 10000) {
  source("/app/ars.R")

  cat("============================================================\n")
  cat(" Adaptive Rejection Sampling — Test Suite\n")
  cat(" Gilks & Wild (1992) Implementation\n")
  cat("============================================================\n\n")

  passed  <- 0
  failed  <- 0

  ## ---- 1. INPUT VALIDATION TESTS ------------------------------------------
  cat("1. Input Validation Tests\n")
  cat("------------------------------------------------------------\n")

  lognorm <- function(x) -0.5 * x^2
  xlow    <- -Inf
  xup     <- Inf
  x0      <- c(-1, 0, 1)

  ## 1a. Negative n
  test_input_negative_n <- function() {
    tryCatch({
      ars(-5, lognorm, xlow, xup, x0)
      return(FALSE)  # should have thrown
    }, error = function(e) grepl("positive integer", e$message, ignore.case = TRUE))
  }
  ok <- test_input_negative_n()
  if (ok) { cat("  INPUT_NEGATIVE_N:   PASS\n"); passed <- passed + 1 } else { cat("  INPUT_NEGATIVE_N:   FAIL\n"); failed <- failed + 1 }

  ## 1b. Non-function log-density
  test_input_non_func <- function() {
    tryCatch({
      ars(10, 42, xlow, xup, x0)
      return(FALSE)
    }, error = function(e) grepl("'logdens' must be a function", e$message))
  }
  ok <- test_input_non_func()
  if (ok) { cat("  INPUT_NON_FUNC:     PASS\n"); passed <- passed + 1 } else { cat("  INPUT_NON_FUNC:     FAIL\n"); failed <- failed + 1 }

  ## 1c. xlow >= xup
  test_input_bounds <- function() {
    tryCatch({
      ars(10, lognorm, 5, 3, x0)
      return(FALSE)
    }, error = function(e) grepl("'xlow' must be strictly less", e$message))
  }
  ok <- test_input_bounds()
  if (ok) { cat("  INPUT_BAD_BOUNDS:   PASS\n"); passed <- passed + 1 } else { cat("  INPUT_BAD_BOUNDS:   FAIL\n"); failed <- failed + 1 }

  ## 1d. Too few initial abscissae
  test_input_few_x0 <- function() {
    tryCatch({
      ars(10, lognorm, xlow, xup, c(0, 1))
      return(FALSE)
    }, error = function(e) grepl("at least 3 points", e$message))
  }
  ok <- test_input_few_x0()
  if (ok) { cat("  INPUT_FEW_X0:       PASS\n"); passed <- passed + 1 } else { cat("  INPUT_FEW_X0:       FAIL\n"); failed <- failed + 1 }

  ## 1e. Initial abscissae outside domain
  test_input_x0_outside <- function() {
    tryCatch({
      ars(10, lognorm, 0, 10, c(-1, 0, 1))
      return(FALSE)
    }, error = function(e) grepl("strictly inside", e$message))
  }
  ok <- test_input_x0_outside()
  if (ok) { cat("  INPUT_X0_OUTSIDE:   PASS\n"); passed <- passed + 1 } else { cat("  INPUT_X0_OUTSIDE:   FAIL\n"); failed <- failed + 1 }

  cat("\n")

  ## ---- 2. NON-LOG-CONCAVE DENSITY TEST ------------------------------------
  cat("2. Log-Concavity Check\n")
  cat("------------------------------------------------------------\n")

  bimodal_logdens <- function(x) log(dnorm(x, mean = -3) + dnorm(x, mean = 3))
  tryCatch({
    ars(100, bimodal_logdens, -Inf, Inf, c(-5, 0, 5))
    cat("  NON_LOG_CONCAVE:  FAIL (no error thrown)\n")
    failed <- failed + 1
  }, error = function(e) {
    if (grepl("Log-concavity violated", e$message, ignore.case = TRUE)) {
      cat("  NON_LOG_CONCAVE:  PASS\n")
      passed <- passed + 1
    } else {
      cat("  NON_LOG_CONCAVE:  FAIL (unexpected error)\n")
      failed <- failed + 1
    }
  })
  cat("\n")

  ## ---- 3. DISTRIBUTIONAL TESTS --------------------------------------------
  cat("3. Distributional Tests\n")
  cat("------------------------------------------------------------\n")

  ## 3a. Standard Normal -------------------------------------------------------
  cat("  [Normal] Generating ", n_samples, " samples ... \n")
  set.seed(42)
  normal_samples <- ars(n_samples,
                         logdens = function(x) -0.5 * x^2,
                         xlow    = -Inf, xup = Inf,
                         x0      = c(-2, 0, 2))
  writeLines(as.character(normal_samples), "/app/normal_samples.txt")
  m  <- mean(normal_samples)
  sd_v <- sd(normal_samples)
  cat("    Mean         : ", round(m, 4), "  (target 0)\n")
  cat("    Std Dev      : ", round(sd_v, 4), "  (target 1)\n")
  if (.ks_test(normal_samples, qnorm, pnorm, alpha = 0.01)) {
    cat("  NORMAL: PASS\n\n")
    passed <- passed + 1
  } else {
    cat("  NORMAL: FAIL\n\n")
    failed <- failed + 1
  }

  ## 3b. Exponential -----------------------------------------------------------
  cat("  [Exponential] Generating ", n_samples, " samples ... \n")
  set.seed(123)
  exp_samples <- ars(n_samples,
                     logdens = function(x) -x,
                     xlow    = 0, xup = Inf,
                     x0      = c(0.1, 1, 3))
  writeLines(as.character(exp_samples), "/app/exponential_samples.txt")
  m  <- mean(exp_samples)
  sd_v <- sd(exp_samples)
  cat("    Mean         : ", round(m, 4), "  (target 1)\n")
  cat("    Std Dev      : ", round(sd_v, 4), "  (target 1)\n")
  if (.ks_test(exp_samples, qexp, pexp, alpha = 0.01)) {
    cat("  EXPONENTIAL: PASS\n\n")
    passed <- passed + 1
  } else {
    cat("  EXPONENTIAL: FAIL\n\n")
    failed <- failed + 1
  }

  ## 3c. Gamma(2,1) ------------------------------------------------------------
  cat("  [Gamma(2,1)] Generating ", n_samples, " samples ... \n")
  set.seed(456)
  gamma_samples <- ars(n_samples,
                       logdens = function(x) (2 - 1) * log(x) - x,
                       xlow    = 0, xup = Inf,
                       x0      = c(0.2, 1, 3))
  m  <- mean(gamma_samples)
  sd_v <- sd(gamma_samples)
  cat("    Mean         : ", round(m, 4), "  (target 2)\n")
  cat("    Std Dev      : ", round(sd_v, 4), "  (target sqrt(2))\n")
  if (.ks_test(gamma_samples, qgamma, pgamma, alpha = 0.01,
               shape = 2, rate = 1)) {
    cat("  GAMMA: PASS\n\n")
    passed <- passed + 1
  } else {
    cat("  GAMMA: FAIL\n\n")
    failed <- failed + 1
  }

  ## 3d. Cauchy (log-concave, heavy-tailed) ------------------------------------
  cat("  [Cauchy] Generating ", n_samples, " samples ... \n")
  set.seed(789)
  cauchy_samples <- ars(n_samples,
                        logdens = function(x) -log(1 + x^2),
                        xlow    = -Inf, xup = Inf,
                        x0      = c(-2, 0, 2))
  m  <- mean(cauchy_samples)
  sd_v <- sd(cauchy_samples)
  cat("    Mean         : ", round(m, 4), "  (undefined for Cauchy)\n")
  cat("    Std Dev      : ", round(sd_v, 4), "  (undefined for Cauchy)\n")
  if (.ks_test(cauchy_samples, qcauchy, pcauchy, alpha = 0.01)) {
    cat("  CAUCHY: PASS\n\n")
    passed <- passed + 1
  } else {
    cat("  CAUCHY: FAIL\n\n")
    failed <- failed + 1
  }

  ## 3e. Log-Normal(0,1) ------------------------------------------------------
  cat("  [LogNormal] Generating ", n_samples, " samples ... \n")
  set.seed(111)
  lnorm_samples <- ars(n_samples,
                       logdens = function(x) -0.5 * (log(x))^2 - log(x),
                       xlow    = 0, xup = Inf,
                       x0      = c(0.1, 1, 5))
  m  <- mean(lnorm_samples)
  sd_v <- sd(lnorm_samples)
  cat("    Mean         : ", round(m, 4), "  (target ", round(exp(0.5), 4), ")\n")
  cat("    Std Dev      : ", round(sd_v, 4), "  (target ", round(sqrt(exp(1)-1)*exp(0.5), 4), ")\n")
  if (.ks_test(lnorm_samples, qlnorm, plnorm, alpha = 0.01)) {
    cat("  LOGNORMAL: PASS\n\n")
    passed <- passed + 1
  } else {
    cat("  LOGNORMAL: FAIL\n\n")
    failed <- failed + 1
  }

  ## ---- 4. SUMMARY -----------------------------------------------------------
  cat("============================================================\n")
  cat(" Summary: ", passed, " passed, ", failed, " failed\n")
  cat("============================================================\n")

  invisible(list(passed = passed, failed = failed))
}

## ---- helper: two-sample KS test (vs theoretical CDF) -----------------------
#' Perform a Kolmogorov-Smirnov goodness-of-fit test against a theoretical CDF.
#'
#' @param samples Numeric vector of samples.
#' @param qfun Quantile function (e.g., qnorm).
#' @param pfun CDF function (e.g., pnorm).
#' @param alpha Significance level.
#' @param ... Additional arguments passed to pfun/qfun.
#' @return Logical; TRUE if the KS test does not reject the null hypothesis
#'   (samples come from the target distribution).
.ks_test <- function(samples, qfun, pfun, alpha = 0.05, ...) {
  # Use one-sample KS test against the theoretical CDF.
  args <- list(...)
  ks_res <- ks.test(samples, pfun, ...)
  sig <- ks_res$p.value < alpha
  direction <- ifelse(sig, "reject H0", "fail to reject H0")
  cat("    KS statistic : ", round(ks_res$statistic, 4),
      ", p-value      : ", format(ks_res$p.value, scientific = FALSE),
      " -> ", direction, "\n", sep = "")
  return(!sig)
}
