{"new_str": ".add_node <- function(state, logdens, xx) {
  idx <- .find_insert_pos(state$x, xx)
  n_nodes <- length(state$x)

  # Skip if point is already in the node set (within numerical tolerance)
  if (any(abs(state$x - xx) < 1e-10)) {
    return(invisible(NULL))
  }

  if (idx == 1) {
    state$x      <- c(xx, state$x)
    state$logf   <- c(logdens(xx), state$logf)
    state$logfp  <- c(.num_derivative(logdens, xx), state$logfp)
  } else if (idx > n_nodes) {
    state$x      <- c(state$x, xx)
    state$logf   <- c(state$logf, logdens(xx))
